@startuml

class CarPark {}

class CardReader {
  + verifyCardNumber()
  + sendSignal()
}

class Signal {}

class StaffCard {
  + name : string
  + department : string
  + staffNumber : int
}

class GuestCard {
  + number : int
  + currentDate : date
}

class Barrier {
  + rise()
}

class Sign {
  + displayStatus()
}

CarPark "1" *-- "2" Barrier
CarPark "1" *-- "1" CardReader
CarPark "1" *-- "1" Sign
CardReader "1" --> "1" Signal
StaffCard "1" -- "1" CardReader
GuestCard "1" -- "1" CardReader

@enduml

